CREATE TABLE IF NOT EXISTS pizzas (id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE, description TEXT NOT NULL, price_cents INTEGER NOT NULL CHECK(price_cents >= 0));
CREATE TABLE IF NOT EXISTS orders (id INTEGER PRIMARY KEY AUTOINCREMENT, status TEXT NOT NULL CHECK(status IN ('RECIBIDO','EN_PREPARACION','LISTO','ENTREGADO')), total_cents INTEGER NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS order_lines (id INTEGER PRIMARY KEY AUTOINCREMENT, order_id INTEGER NOT NULL, pizza_id INTEGER NOT NULL, pizza_name TEXT NOT NULL, unit_price_cents INTEGER NOT NULL, quantity INTEGER NOT NULL CHECK(quantity > 0), FOREIGN KEY(order_id) REFERENCES orders(id), FOREIGN KEY(pizza_id) REFERENCES pizzas(id));
CREATE TABLE IF NOT EXISTS sales_reports (id INTEGER PRIMARY KEY AUTOINCREMENT, report_date TEXT NOT NULL UNIQUE, order_count INTEGER NOT NULL, total_cents INTEGER NOT NULL, by_status TEXT NOT NULL, generated_at TEXT NOT NULL);
